#include "LogComponents.h"
#include "se-log/Log.h"
#include "se-log/LogRegistryBuilder.h"
#include "se-log/sink/ConsoleSink.h"
#include "se-log/LogRegistry.h"
#include "se-log/format/JsonFormatter.h"
#include "se-log/format/StringFormatter.h"


static constexpr selog::Hash hashihash {"hello world"};
static constexpr selog::ValueType valuetypy {42U};

int main()
{
    auto shellSink = std::make_unique<selog::PrintfSink>();
    auto fileSink = std::make_unique<selog::PrintfSink>();

    auto formatter = std::make_unique<selog::StringFormatter>();
    // auto formatter = std::make_unique<selog::JsonFormatter>();

    auto logRegistry =
        selog::LogRegistryBuilder<LogComponents, LogSinks>()
            .setFormatter(std::move(formatter))
            //.useBuffer()
            .attachSink(LogSinks::SHELL, std::move(shellSink))
            .attachSink(LogSinks::FILE, std::move(fileSink))
            .build();

    logRegistry->getSink(LogSinks::SHELL).setLogLevel(selog::Level::WARN);

    selog::Logger& loggerCellular = logRegistry->getLogger(LogComponents::CELLULAR);
    selog::Logger& loggerWuff = logRegistry->getLogger(LogComponents::WUFF);

    loggerCellular.setLevel(selog::Level::TRACE);

    loggerCellular.trace("trace");
    loggerCellular.debug("debug");
    loggerCellular.info("info");
    loggerCellular.warn("warn");
    loggerCellular.error("error");
    loggerCellular.fatal("fatal");

    for (uint32_t i = 0; i < 10; ++i) {
        loggerCellular.info("hello %u", i);
    }

    logRegistry->getLogger(LogComponents::WUFF).setLevel(selog::Level::WARN);

    loggerWuff.warn("wuff");

    selog::Logger& loggerStorage = logRegistry->getLogger(LogComponents::STORAGE);
    loggerStorage.info("values {}", 1U);
    loggerStorage.info("values %u, %u", 1U, 2U);
    loggerStorage.info("values %u, %u, %u", 1U, 2U, 3U);
    loggerStorage.info("values %u, %u, %u, %u", 1U, 2U, 3U, 4U);
    loggerStorage.info("values with floats %f", 42.0F);
    loggerStorage.info("values with floats %f, %u", 42.0F, 2U);
    loggerStorage.info("values negative %f, %d", -42.0F, -2);

    loggerCellular.info("my hash %u, valuey %u", hashihash.hash(), valuetypy.value());

    // constexpr uint32_t strhash = COMPILE_TIME_CRC32_STR("");
    // loggerStorage.info("my hash %u", strhash);
    loggerStorage.info("my hash %u", COMPILE_TIME_CRC32_STR(""));
    // loggerStorage.info("");
    return 0;
}
